window.LF_STUDIO_SHELL_TEMPLATE = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <base href=\"__LF_BASE__\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#f5f5f5\">\n  <meta name=\"description\" content=\"LiteraryFriend Studio design shell for book cover design and book building.\">\n  <title>LiteraryFriend Studio</title>\n  <link rel=\"icon\" href=\"assets/images/Icon.png\" type=\"image/png\">\n  <link rel=\"apple-touch-icon\" href=\"assets/icon-180.png\">\n  <link rel=\"stylesheet\" href=\"css/base-studio.css\">\n  <link rel=\"stylesheet\" href=\"css/project-hub-studio.css\">\n  <link rel=\"stylesheet\" href=\"css/studio-shell.css\">\n  <link rel=\"stylesheet\" href=\"css/ribbon-studio.css\">\n  <link rel=\"stylesheet\" href=\"css/responsive-studio.css\">\n  <style>\n    .workspace-shell{position:relative}\n    .integrated-studio-host{position:absolute;inset:0;z-index:40;background:var(--panel,#f1f1f1);min-width:0;min-height:0}\n    .integrated-studio-host[hidden]{display:none!important}\n    .integrated-studio-frame{display:block;width:100%;height:100%;border:0;background:#776f62}\n    .panel-section.is-not-used{opacity:.58}\n    .panel-section.is-not-used::after{content:\"Cover Base is used for Book Cover projects\";display:block;margin-top:8px;font-size:.78rem;color:var(--muted,#667)}\n    .launch-selection-summary{margin-top:8px;font-weight:700}\n  </style>\n</head>\n<body>\n  <div id=\"app\" class=\"app-shell\" data-theme=\"light\">\n    <section id=\"projectHub\" class=\"project-hub\" aria-label=\"Project entrance\">\n      <header class=\"hub-topbar\">\n        <div class=\"brand-lockup\" aria-label=\"LiteraryFriend Studio\">\n          <span class=\"brand-literaryfriend\">LiteraryFriend</span><span class=\"brand-rest\"> Studio</span>\n        </div>\n        <div class=\"hub-actions\">\n          <label class=\"theme-switch\">\n            <span>Dark mode</span>\n            <input id=\"darkModeToggle\" type=\"checkbox\" aria-label=\"Toggle dark mode\">\n            <span class=\"switch-track\" aria-hidden=\"true\"><span class=\"switch-knob\"></span></span>\n          </label>\n          <button class=\"icon-button settings-button\" type=\"button\" aria-label=\"Settings\" data-command=\"settings\">⚙</button>\n        </div>\n      </header>\n\n      <main class=\"hub-grid\">\n        <section class=\"hub-panel hub-panel-left\" aria-label=\"Project setup\">\n          <div class=\"panel-section\">\n            <h2>Cover Base</h2>\n            <div id=\"backgroundChoices\" class=\"background-choices\" role=\"radiogroup\" aria-label=\"Cover base\">\n              <button class=\"background-swatch selected transparent-swatch\" type=\"button\" data-background=\"transparent\" aria-label=\"Transparent cover base\" aria-pressed=\"true\"><span class=\"swatch-mark\">T</span></button>\n              <button class=\"background-swatch\" type=\"button\" data-background=\"#ffffff\" aria-label=\"White cover base\"></button>\n              <button class=\"background-swatch dark-swatch\" type=\"button\" data-background=\"#111111\" aria-label=\"Black cover base\"></button>\n              <button class=\"background-swatch\" style=\"--swatch:#ff3b30\" type=\"button\" data-background=\"#ff3b30\" aria-label=\"Red cover base\"></button>\n              <button class=\"background-swatch\" style=\"--swatch:#ec176a\" type=\"button\" data-background=\"#ec176a\" aria-label=\"Pink-red cover base\"></button>\n              <button class=\"background-swatch\" style=\"--swatch:#a52ac4\" type=\"button\" data-background=\"#a52ac4\" aria-label=\"Purple cover base\"></button>\n              <button class=\"background-swatch\" style=\"--swatch:#178de8\" type=\"button\" data-background=\"#178de8\" aria-label=\"Blue cover base\"></button>\n              <button class=\"background-swatch gradient-mono\" type=\"button\" data-background=\"gradient:mono\" aria-label=\"Black to white gradient\"></button>\n              <button class=\"background-swatch gradient-sunset\" type=\"button\" data-background=\"gradient:sunset\" aria-label=\"Sunset gradient\"></button>\n              <button class=\"background-swatch gradient-earth\" type=\"button\" data-background=\"gradient:earth\" aria-label=\"Earth gradient\"></button>\n              <button class=\"background-swatch gradient-spring\" type=\"button\" data-background=\"gradient:spring\" aria-label=\"Spring gradient\"></button>\n              <button class=\"background-swatch gradient-ocean\" type=\"button\" data-background=\"gradient:ocean\" aria-label=\"Ocean gradient\"></button>\n            </div>\n          </div>\n\n          <div class=\"panel-section import-card\">\n            <div class=\"import-card-copy\">\n              <strong>Import</strong>\n              <span>Open an existing LiteraryFriend project or supported source file.</span>\n            </div>\n            <button id=\"importProjectButton\" class=\"chevron-button\" type=\"button\" aria-label=\"Import a project\">›</button>\n            <input id=\"projectFileInput\" type=\"file\" hidden accept=\".json,.lfart,.txt,.md,.docx,.pdf,.html,.htm,.rtf,.csv,.xml,image/*\">\n          </div>\n\n          <div class=\"panel-section\">\n            <h2>Project Type</h2>\n            <div id=\"projectTypeTabs\" class=\"segmented-control\" role=\"radiogroup\" aria-label=\"Project type\">\n              <button class=\"segment selected\" type=\"button\" data-project-type=\"book-cover\" aria-pressed=\"true\">Book Cover</button>\n              <button class=\"segment\" type=\"button\" data-project-type=\"book-building\" aria-pressed=\"false\">Book Building</button>\n            </div>\n            <div class=\"project-type-card-grid\">\n              <button class=\"project-type-card selected\" type=\"button\" data-project-type=\"book-cover\">\n                <span class=\"type-card-title\">Book Cover</span>\n                <span class=\"type-card-meta\">Front cover canvas, typography, layers, effects, and 3D tools.</span>\n              </button>\n              <button class=\"project-type-card\" type=\"button\" data-project-type=\"book-building\">\n                <span class=\"type-card-title\">Book Building</span>\n                <span class=\"type-card-meta\">Page-based workspace with trim presets, page navigation, and layout tools.</span>\n              </button>\n            </div>\n          </div>\n\n          <div class=\"panel-section size-section\">\n            <h2>Book Size</h2>\n            <label class=\"select-label\" for=\"bookSizeSelect\">Trim preset</label>\n            <select id=\"bookSizeSelect\" class=\"book-size-select\"></select>\n            <div id=\"sizeSummary\" class=\"size-summary\" aria-live=\"polite\"></div>\n            <div id=\"launchSelectionSummary\" class=\"size-summary launch-selection-summary\" aria-live=\"polite\"></div>\n          </div>\n        </section>\n\n        <section class=\"hub-panel hub-panel-right\" aria-label=\"Projects and saved work\">\n          <div class=\"panel-section grow-section\">\n            <div class=\"section-heading-row\"><h2>Projects</h2><button id=\"newProjectSmall\" class=\"text-button\" type=\"button\">New Project</button></div>\n            <div id=\"projectsEmptyState\" class=\"empty-state\">\n              <div class=\"empty-icon folder-icon\" aria-hidden=\"true\"></div>\n              <h3>No projects yet</h3>\n              <p>Create your first project to get started.</p>\n              <button id=\"newProjectButton\" class=\"primary-button\" type=\"button\">+ New Project</button>\n            </div>\n            <div id=\"projectCards\" class=\"project-cards\" hidden></div>\n          </div>\n\n          <div class=\"panel-section grow-section saved-section\">\n            <h2>Saved Work</h2>\n            <div id=\"savedEmptyState\" class=\"empty-state compact\">\n              <div class=\"empty-icon page-icon\" aria-hidden=\"true\"></div>\n              <h3>No saved work yet</h3>\n              <p>Saved pages and covers will appear here.</p>\n            </div>\n            <div id=\"savedCards\" class=\"saved-cards\" hidden></div>\n          </div>\n        </section>\n      </main>\n    </section>\n\n    <section id=\"studioShell\" class=\"studio-shell\" aria-label=\"LiteraryFriend editor\" hidden>\n      <header class=\"studio-titlebar\">\n        <div class=\"studio-brand\"><span class=\"brand-literaryfriend\">LiteraryFriend</span><span class=\"brand-rest\"> Studio</span></div>\n        <div id=\"projectTitle\" class=\"project-title\" contenteditable=\"true\" spellcheck=\"false\" aria-label=\"Project title\">Untitled Project</div>\n        <div class=\"titlebar-actions\">\n          <button id=\"backToHubButton\" class=\"titlebar-button\" type=\"button\">Projects</button>\n          <button id=\"saveButton\" class=\"titlebar-button primary\" type=\"button\">Save</button>\n        </div>\n      </header>\n\n      <nav class=\"menu-bar\" aria-label=\"Application menu\">\n        <button class=\"menu-item\" type=\"button\" data-menu=\"file\">File</button>\n        <button class=\"menu-item\" type=\"button\" data-menu=\"edit\">Edit</button>\n        <button class=\"menu-item\" type=\"button\" data-menu=\"view\">View</button>\n      </nav>\n\n      <div class=\"ribbon\" role=\"toolbar\" aria-label=\"Studio tools\">\n        <div class=\"ribbon-group selection-group\">\n          <button class=\"ribbon-main tool-button active\" type=\"button\" data-tool=\"select\"><span class=\"tool-glyph select-glyph\"></span><span>Selection</span></button>\n        </div>\n        <div class=\"ribbon-group\">\n          <div class=\"mini-grid\">\n            <button class=\"mini-tool\" type=\"button\" data-command=\"crop\" title=\"Crop\">Crop</button>\n            <button class=\"mini-tool\" type=\"button\" data-command=\"resize\" title=\"Resize\">Resize</button>\n            <button class=\"mini-tool\" type=\"button\" data-command=\"rotate\" title=\"Rotate\">Rotate</button>\n            <button class=\"mini-tool\" type=\"button\" data-command=\"flip\" title=\"Flip\">Flip</button>\n          </div>\n          <span class=\"ribbon-label\">Image</span>\n        </div>\n        <div class=\"ribbon-group tools-group\">\n          <div class=\"tool-grid\">\n            <button class=\"tool-button\" type=\"button\" data-tool=\"pencil\" title=\"Pencil\">Pencil</button>\n            <button class=\"tool-button\" type=\"button\" data-tool=\"fill\" title=\"Fill\">Fill</button>\n            <button class=\"tool-button\" type=\"button\" data-tool=\"text\" title=\"Text\">Text</button>\n            <button class=\"tool-button\" type=\"button\" data-tool=\"eraser\" title=\"Eraser\">Eraser</button>\n            <button class=\"tool-button\" type=\"button\" data-tool=\"eyedropper\" title=\"Color picker\">Picker</button>\n            <button class=\"tool-button\" type=\"button\" data-tool=\"zoom\" title=\"Zoom\">Zoom</button>\n          </div>\n          <span class=\"ribbon-label\">Tools</span>\n        </div>\n        <div class=\"ribbon-group brushes-group\">\n          <button class=\"brush-preview tool-button\" type=\"button\" data-tool=\"brush\"><span class=\"brush-stroke\"></span><span>Brushes</span></button>\n          <select id=\"brushTypeSelect\" class=\"ribbon-select\" aria-label=\"Brush type\">\n            <option value=\"round\">Round</option><option value=\"marker\">Marker</option><option value=\"pencil\">Pencil</option><option value=\"airbrush\">Airbrush</option>\n          </select>\n          <input id=\"brushSize\" type=\"range\" min=\"1\" max=\"120\" value=\"12\" aria-label=\"Brush size\">\n        </div>\n        <div class=\"ribbon-group shapes-group\">\n          <div id=\"shapeGrid\" class=\"shape-grid\">\n            <button class=\"shape-button\" data-shape=\"line\" type=\"button\" title=\"Line\">／</button>\n            <button class=\"shape-button\" data-shape=\"rectangle\" type=\"button\" title=\"Rectangle\">□</button>\n            <button class=\"shape-button\" data-shape=\"ellipse\" type=\"button\" title=\"Ellipse\">○</button>\n            <button class=\"shape-button\" data-shape=\"triangle\" type=\"button\" title=\"Triangle\">△</button>\n            <button class=\"shape-button\" data-shape=\"diamond\" type=\"button\" title=\"Diamond\">◇</button>\n            <button class=\"shape-button\" data-shape=\"arrow\" type=\"button\" title=\"Arrow\">→</button>\n          </div>\n          <span class=\"ribbon-label\">Shapes</span>\n        </div>\n        <div class=\"ribbon-group colors-group\">\n          <div class=\"current-colors\"><button id=\"primaryColor\" class=\"current-color primary-current\" type=\"button\" title=\"Primary color\"></button><button id=\"secondaryColor\" class=\"current-color secondary-current\" type=\"button\" title=\"Secondary color\"></button></div>\n          <div id=\"colorPalette\" class=\"color-palette\" aria-label=\"Color palette\"></div>\n          <label class=\"custom-color-button\" title=\"Custom color\"><input id=\"customColorInput\" type=\"color\" value=\"#00a8e8\"><span>+</span></label>\n          <span class=\"ribbon-label\">Colors</span>\n        </div>\n        <div class=\"ribbon-group three-d-group\">\n          <button id=\"threeDButton\" class=\"three-d-button\" type=\"button\" aria-expanded=\"false\" aria-controls=\"threeDPanel\"><span class=\"three-d-mark\">3D</span></button>\n          <span class=\"ribbon-label\">3D</span>\n        </div>\n        <div class=\"ribbon-group layers-group\">\n          <button id=\"layersButton\" class=\"layers-button\" type=\"button\" aria-expanded=\"true\" aria-controls=\"layersPanel\"><span class=\"layer-stack\" aria-hidden=\"true\"></span></button>\n          <span class=\"ribbon-label\">Layers</span>\n        </div>\n      </div>\n\n      <main class=\"workspace-shell\">\n        <aside id=\"pageRail\" class=\"page-rail\" aria-label=\"Book pages\" hidden>\n          <div class=\"page-rail-header\"><strong>Pages</strong><button id=\"addPageButton\" type=\"button\" aria-label=\"Add page\">+</button></div>\n          <div id=\"pageList\" class=\"page-list\"></div>\n        </aside>\n\n        <aside class=\"left-tool-rail\" aria-label=\"Brush controls\">\n          <label><span>Size</span><input id=\"verticalBrushSize\" type=\"range\" min=\"1\" max=\"120\" value=\"12\" orient=\"vertical\"></label>\n          <label><span>Opacity</span><input id=\"brushOpacity\" type=\"range\" min=\"1\" max=\"100\" value=\"100\" orient=\"vertical\"></label>\n        </aside>\n\n        <section class=\"stage-wrap\" aria-label=\"Canvas workspace\">\n          <div id=\"integratedStudioHost\" class=\"integrated-studio-host\" hidden aria-label=\"Integrated LiteraryFriend Book Cover and Book Building tools\">\n            <iframe id=\"integratedStudioFrame\" class=\"integrated-studio-frame\" title=\"LiteraryFriend integrated studio tools\" allow=\"clipboard-read; clipboard-write\"></iframe>\n          </div>\n          <div id=\"studioStage\" class=\"studio-stage\" data-size=\"paperback-digest\" data-background=\"transparent\">\n            <div id=\"canvasFrame\" class=\"canvas-frame transparency-surface\" aria-label=\"Transparent canvas area\">\n              <canvas id=\"artCanvas\" width=\"1650\" height=\"2550\"></canvas>\n              <div id=\"selectionOverlay\" class=\"selection-overlay\" hidden></div>\n              <textarea id=\"textEditor\" class=\"canvas-text-editor\" hidden aria-label=\"Text entry\"></textarea>\n            </div>\n          </div>\n        </section>\n\n        <aside id=\"propertyDock\" class=\"property-dock\" aria-label=\"Properties\">\n          <section id=\"threeDPanel\" class=\"dock-panel\" hidden>\n            <div class=\"dock-heading\"><strong>3D</strong><button class=\"dock-close\" type=\"button\" data-close-panel=\"threeDPanel\">×</button></div>\n            <label>Extrude <input id=\"extrudeRange\" type=\"range\" min=\"0\" max=\"100\" value=\"20\"></label>\n            <label>Bevel <input id=\"bevelRange\" type=\"range\" min=\"0\" max=\"50\" value=\"5\"></label>\n            <label>Rotate X <input id=\"rotateXRange\" type=\"range\" min=\"-180\" max=\"180\" value=\"0\"></label>\n            <label>Rotate Y <input id=\"rotateYRange\" type=\"range\" min=\"-180\" max=\"180\" value=\"0\"></label>\n            <label>Rotate Z <input id=\"rotateZRange\" type=\"range\" min=\"-180\" max=\"180\" value=\"0\"></label>\n            <button id=\"apply3DButton\" class=\"dock-action\" type=\"button\">Apply to Selection</button>\n          </section>\n\n          <section id=\"layersPanel\" class=\"dock-panel\">\n            <div class=\"dock-heading\"><strong>Layers</strong><button id=\"addLayerButton\" type=\"button\">+</button></div>\n            <div id=\"layerList\" class=\"layer-list\"></div>\n          </section>\n        </aside>\n      </main>\n\n      <footer class=\"status-bar\">\n        <div id=\"pointerStatus\">0 × 0 px</div>\n        <div id=\"documentStatus\">1650 × 2550 px</div>\n        <div id=\"saveStatus\">Local draft</div>\n        <div class=\"zoom-controls\"><button id=\"zoomOutButton\" type=\"button\">−</button><span id=\"zoomLabel\">100%</span><input id=\"zoomRange\" type=\"range\" min=\"10\" max=\"300\" value=\"100\"><button id=\"zoomInButton\" type=\"button\">+</button></div>\n      </footer>\n    </section>\n\n    <div id=\"toastRegion\" class=\"toast-region\" aria-live=\"polite\" aria-atomic=\"true\"></div>\n  </div>\n\n  <script src=\"js/backend-client-studio.js\"></script>\n  <script src=\"js/size-loader-studio.js\"></script>\n  <script src=\"js/canvas-engine-studio.js\"></script>\n  <script src=\"js/project-store-studio.js\"></script>\n  <script src=\"js/studio-ui.js\"></script>\n  <script src=\"js/integrated-template-studio.js\"></script>\n  <script src=\"js/integration-host-studio.js\"></script>\n  <script src=\"js/studio-context-bridge.js\"></script>\n  <script src=\"js/app-studio.js\"></script>\n  <script src=\"js/superbot-host-studio.js\"></script>\n</body>\n</html>\n";
